package local.m13.home;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import org.json.*;

/** All personal configuration works with the TV remote and stays on the box. */
public final class LauncherSettingsActivity extends Activity {
    private int section;
    private LinearLayout body;private TextView heading;private static final int SAVE=31,OPEN=32;
    private int dp(int n){return TvUi.dp(this,n);}
    public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(1024,1024);ScreenPolicy.applyWindow(this);menu();}
    private void page(String title){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(48),dp(24),dp(48),dp(24));root.setBackground(BlueRedTheme.background(0));heading=new TextView(this);heading.setText(title);heading.setTextSize(26);heading.setTextColor(BlueRedTheme.TEXT);root.addView(heading,new LinearLayout.LayoutParams(-1,dp(58)));ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);TvUi.inset(this);}
    private void item(String text,final Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(16);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.bottomMargin=dp(8);body.addView(b,p);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){action.run();}});if(body.getChildCount()==1)b.requestFocus();}
    private void note(String message){TextView t=new TextView(this);t.setText(message);t.setTextSize(14);t.setTextColor(BlueRedTheme.MUTED);t.setPadding(0,dp(6),0,dp(14));body.addView(t);}
    private void info(String text){new AlertDialog.Builder(this).setMessage(text).setPositiveButton("确定",null).show();}
    private void menu(){section=0;page("轻桌面设置");item("电视画面边距",new Runnable(){public void run(){TvUi.choose(LauncherSettingsActivity.this,new Runnable(){public void run(){menu();}});}});item("课程表与临时调课",new Runnable(){public void run(){courses();}});item("设置备份与恢复",new Runnable(){public void run(){backups();}});item("检查更新与旧版安装包",new Runnable(){public void run(){startActivity(new Intent(LauncherSettingsActivity.this,LauncherUpdateActivity.class));}});item("返回桌面",new Runnable(){public void run(){finish();}});note("返回键关闭当前弹窗；在本页返回桌面。画面边距适用于桌面、音乐、投屏说明和课程屏保，不裁切影视画面。");}
    private void courses(){section=1;page("课程表");final String[] names={"星期一","星期二","星期三","星期四","星期五","星期六","星期日"};for(int n=0;n<7;n++){final int day=n;item(names[n]+" · 编辑七节课程",new Runnable(){public void run(){try{editDay(day,null);}catch(Exception e){info(e.getMessage());}}});}item("指定日期 · 临时调课或放假",new Runnable(){public void run(){Calendar c=Calendar.getInstance(TimeZone.getTimeZone("Asia/Shanghai"));DatePickerDialog picker=new DatePickerDialog(LauncherSettingsActivity.this,new DatePickerDialog.OnDateSetListener(){public void onDateSet(DatePicker view,int y,int m,int d){exception(String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d));}},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH));picker.show();}});item("查看 / 删除临时安排",new Runnable(){public void run(){exceptions();}});item("返回设置",new Runnable(){public void run(){menu();}});}
    private void exception(final String date){new AlertDialog.Builder(this).setTitle(date).setItems(new String[]{"当天放假 · 屏保跳到下一上课日","当天调课 · 编辑七节课程","恢复每周常规安排"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){try{if(which==1){editDay(-1,date);return;}JSONObject config=CrayonTimetableStore.config(LauncherSettingsActivity.this);JSONArray off=config.optJSONArray("holidays"),next=new JSONArray();if(off!=null)for(int n=0;n<off.length();n++)if(!date.equals(off.getString(n)))next.put(off.getString(n));if(which==0)next.put(date);config.put("holidays",next);JSONObject overrides=config.optJSONObject("overrides");if(overrides!=null)overrides.remove(date);CrayonTimetableStore.configure(LauncherSettingsActivity.this,config.toString());info("已保存 "+date+" 的安排");}catch(Exception e){info(e.getMessage());}}}).setNegativeButton("返回",null).show();}
    private void exceptions(){try{JSONObject config=CrayonTimetableStore.config(this);TreeSet<String> dates=new TreeSet<String>();JSONArray off=config.optJSONArray("holidays");if(off!=null)for(int n=0;n<off.length();n++)dates.add(off.getString(n));JSONObject changes=config.optJSONObject("overrides");if(changes!=null){Iterator<String> keys=changes.keys();while(keys.hasNext())dates.add(keys.next());}if(dates.isEmpty()){info("没有临时安排");return;}final String[] all=dates.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("临时安排 · 选择日期可修改或恢复").setItems(all,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){exception(all[n]);}}).setNegativeButton("返回",null).show();}catch(Exception e){info(e.getMessage());}}
    private void editDay(final int day,final String date)throws Exception{final JSONObject config=CrayonTimetableStore.config(this);JSONArray initial=date==null?config.getJSONArray("week").getJSONArray(day):config.optJSONObject("overrides")==null?null:config.getJSONObject("overrides").optJSONArray(date);if(initial==null&&date!=null){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);Calendar c=Calendar.getInstance();c.setTime(f.parse(date));initial=config.getJSONArray("week").getJSONArray((c.get(Calendar.DAY_OF_WEEK)+5)%7);}section=2;final String[] values=new String[7];for(int n=0;n<7;n++)values[n]=initial!=null?initial.optString(n,""):"";page(date==null?"编辑 · 周"+new String[]{"一","二","三","四","五","六","日"}[day]:"调课 · "+date);note("选择课节修改；可用常见课程或输入名称。未安排的课节显示“自习”。按返回不保存。");for(int n=0;n<7;n++){final int slot=n;item((n+1)+" · "+(values[n].isEmpty()?"自习":values[n]),new Runnable(){public void run(){final Button button=(Button)body.getChildAt(slot+1);chooseCourse(values,slot,button);}});}item("保存七节课程",new Runnable(){public void run(){try{JSONArray lessons=new JSONArray();for(String value:values)lessons.put(value.isEmpty()?"自习":value);if(date==null)config.getJSONArray("week").put(day,lessons);else{JSONObject changes=config.optJSONObject("overrides");if(changes==null)changes=new JSONObject();changes.put(date,lessons);config.put("overrides",changes);JSONArray old=config.optJSONArray("holidays"),off=new JSONArray();if(old!=null)for(int n=0;n<old.length();n++)if(!date.equals(old.getString(n)))off.put(old.getString(n));config.put("holidays",off);}CrayonTimetableStore.configure(LauncherSettingsActivity.this,config.toString());courses();info("课程已保存");}catch(Exception e){info(e.getMessage());}}});if(date==null)item("设为休息日（清空当天）",new Runnable(){public void run(){try{config.getJSONArray("week").put(day,new JSONArray());CrayonTimetableStore.configure(LauncherSettingsActivity.this,config.toString());courses();}catch(Exception e){info(e.getMessage());}}});}
    private void chooseCourse(final String[] values,final int slot,final Button button){final String[] subjects={"语文","数学","英语","科学","信息科技","体育与健康","阳光体育","音乐","美术","道德与法治","劳动","综合实践活动","少先队活动","自习","自定义…"};new AlertDialog.Builder(this).setTitle("第 "+(slot+1)+" 节").setItems(subjects,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){if(n<subjects.length-1){values[slot]=subjects[n];button.setText((slot+1)+" · "+values[slot]);return;}final EditText input=new EditText(LauncherSettingsActivity.this);input.setSingleLine();input.setText(values[slot]);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(32)});new AlertDialog.Builder(LauncherSettingsActivity.this).setTitle("课程名称").setView(input).setPositiveButton("确定",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){values[slot]=input.getText().toString().trim();button.setText((slot+1)+" · "+(values[slot].isEmpty()?"自习":values[slot]));}}).setNegativeButton("返回",null).show();}}).setNegativeButton("返回",null).show();}
    private File local(){return new File(getFilesDir(),"settings-backup.json");}
    private void backups(){section=1;page("设置备份与恢复");note("包含首页排序、课程表、临时安排、屏保配色和音乐显示偏好。不包含账号、Cookie、观看记录或系统固件。外部文件含个人课程，请自行保管。");item("保存一份到盒子",new Runnable(){public void run(){try{LauncherBackup.write(local(),LauncherBackup.export(LauncherSettingsActivity.this).toString(2));info("已保存到盒子。" );}catch(Exception e){info(e.getMessage());}}});item("从盒子备份恢复",new Runnable(){public void run(){try{InputStream in=new FileInputStream(local());JSONObject root;try{root=LauncherBackup.read(in);}finally{in.close();}confirmRestore(root);}catch(Exception e){info("没有可用备份："+e.getMessage());}}});item("导出到 U 盘 / 文件",new Runnable(){public void run(){try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"轻桌面设置备份.json"),SAVE);}catch(Exception e){info("此系统没有文件选择器。可以先保存到盒子。");}}});item("从 U 盘 / 文件导入",new Runnable(){public void run(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),OPEN);}catch(Exception e){info("此系统没有文件选择器，请使用盒子内的备份。");}}});item("撤销上次恢复",new Runnable(){public void run(){try{InputStream in=new FileInputStream(new File(getFilesDir(),"settings-before-restore.json"));JSONObject root;try{root=LauncherBackup.read(in);}finally{in.close();}confirmRestore(root);}catch(Exception e){info("还没有可撤销的恢复记录");}}});item("返回设置",new Runnable(){public void run(){menu();}});}
    private void confirmRestore(final JSONObject data)throws Exception{LauncherBackup.validate(data);new AlertDialog.Builder(this).setTitle("恢复这份设置？").setMessage("覆盖首页、课程和显示偏好。恢复前会自动保存当前设置，之后可撤销。账号和系统主页配置不变。").setPositiveButton("恢复",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){try{LauncherBackup.restore(LauncherSettingsActivity.this,data);TvUi.inset(LauncherSettingsActivity.this);info("设置已恢复，返回桌面即可看到。" );}catch(Exception e){info("恢复未完成："+e.getMessage());}}}).setNegativeButton("取消",null).show();}
    public void onBackPressed(){if(section==2)courses();else if(section==1)menu();else finish();}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;try{if(request==SAVE){OutputStream out=getContentResolver().openOutputStream(data.getData());try{out.write(LauncherBackup.export(this).toString(2).getBytes("UTF-8"));}finally{out.close();}info("设置备份已导出");}else if(request==OPEN){InputStream in=getContentResolver().openInputStream(data.getData());JSONObject root;try{root=LauncherBackup.read(in);}finally{in.close();}confirmRestore(root);}}catch(Exception e){info("文件操作未完成："+e.getMessage());}}
}
